settings.liquid:
{%- comment -%}
CURVJEANS — Social Proof Badge (With Divider)
{%- endcomment -%}
{%- liquid
assign _lc = request.locale.iso_code | downcase
case _lc
  when "nl"
    assign spt = "Geliefd door <strong>20.000+</strong> vrouwen"
  when "de"
    assign spt = "Geliebt von <strong>20.000+</strong> Frauen"
  else
    assign spt = "Worn & Loved by <strong>20,000+</strong> women"
endcase
-%}
<div class="cj-spb-section">
  <div class="cj-spb-wrapper">
    <span>{{ spt }}</span>
    <img class="cj-spb-verified"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/verified.webp?v=1726649878"
         alt="verified">
  </div>
  <div class="cj-spb-divider"></div>
</div>
<style>
.cj-spb-section {
  background: #fff;
}
.cj-spb-wrapper {
  text-align: center;
  padding: 20px 16px 16px;
  font-size: 14px;
  font-weight: 500;
  color: #666;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 4px;
}
.cj-spb-wrapper strong {
  font-weight: 700;
  color: #333;
}
.cj-spb-verified {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}
.cj-spb-divider {
  width: 60px;
  height: 1px;
  background: #e0e0e0;
  margin: 0 auto 20px;
}
@media (max-width: 640px) {
  .cj-spb-wrapper {
    font-size: 13px;
    padding: 16px 16px 12px;
  }
  .cj-spb-divider {
    margin-bottom: 0px;
  }
}
</style>

{%- assign lc = request.locale.iso_code | downcase -%}
{%- assign path = request.path | downcase -%}

<div class="cj-subcollection-nav" aria-label="Collection navigation" data-cj-ajax-collections>
  <a 
    class="cj-subcollection-link {% if request.path contains '/collections/all-products' %}is-active{% endif %}" 
    href="/collections/all-products"
    data-cj-collection-link
  >
    {%- if path contains '/nl' or lc == 'nl' -%}
      Alles
    {%- elsif path contains '/de' or lc == 'de' -%}
      Alle
    {%- else -%}
      All
    {%- endif -%}
  </a>

  <a 
    class="cj-subcollection-link {% if request.path contains '/collections/new' %}is-active{% endif %}" 
    href="/collections/new"
    data-cj-collection-link
  >
    {%- if path contains '/nl' or lc == 'nl' -%}
      Nieuw
    {%- elsif path contains '/de' or lc == 'de' -%}
      Neu
    {%- else -%}
      New
    {%- endif -%}
  </a>

  <a 
    class="cj-subcollection-link {% if request.path contains '/collections/bestsellers' %}is-active{% endif %}" 
    href="/collections/bestsellers"
    data-cj-collection-link
  >
    Bestsellers
  </a>

  <a 
    class="cj-subcollection-link {% if request.path contains '/collections/high-waist' %}is-active{% endif %}" 
    href="/collections/high-waist"
    data-cj-collection-link
  >
    High Waist
  </a>

  <a 
    class="cj-subcollection-link {% if request.path contains '/collections/mid-rise' %}is-active{% endif %}" 
    href="/collections/mid-rise"
    data-cj-collection-link
  >
    Mid Rise
  </a>

  <a 
    class="cj-subcollection-link {% if request.path contains '/collections/sale' %}is-active{% endif %}" 
    href="/collections/sale"
    data-cj-collection-link
  >
    Sale
  </a>
</div>

<style>
  .cj-subcollection-nav {
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: flex-end;
    gap: 36px;
    margin: 26px auto 32px;
    padding: 0 24px 13px;
    border-bottom: 1px solid rgba(0, 0, 0, 0.10);
    font-family: inherit;
  }

  .cj-subcollection-nav.is-loading {
    opacity: 0.55;
    pointer-events: none;
  }

  .cj-subcollection-link {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0 0 12px;
    color: rgba(0, 0, 0, 0.42) !important;
    text-decoration: none !important;
    font-size: 16px;
    line-height: 1;
    font-weight: 400;
    letter-spacing: -0.02em;
    white-space: nowrap;
    transition: color 0.18s ease;
  }

  .cj-subcollection-link:hover {
    color: rgba(0, 0, 0, 0.78) !important;
  }

  .cj-subcollection-link.is-active {
    color: #111 !important;
    font-weight: 500;
  }

  .cj-subcollection-link.is-active::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: -14px;
    height: 3px;
    background: #111;
    border-radius: 999px;
  }

  @media (max-width: 768px) {
    .cj-subcollection-nav {
      justify-content: flex-start;
      gap: 28px;
      margin: 20px auto 26px;
      padding: 0 16px 12px;
      overflow-x: auto;
      overflow-y: hidden;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
    }

    .cj-subcollection-nav::-webkit-scrollbar {
      display: none;
    }

    .cj-subcollection-link {
      flex: 0 0 auto;
      font-size: 14px;
      padding-bottom: 11px;
    }

    .cj-subcollection-link.is-active::after {
      bottom: -13px;
      height: 3px;
    }
  }

  @media (max-width: 390px) {
    .cj-subcollection-nav {
      gap: 24px;
    }

    .cj-subcollection-link {
      font-size: 14px;
    }
  }
</style>

<script>
  document.addEventListener('DOMContentLoaded', function () {
    const nav = document.querySelector('[data-cj-ajax-collections]');
    if (!nav) return;

    const links = nav.querySelectorAll('[data-cj-collection-link]');

    function findCollectionArea(doc) {
      return (
        doc.querySelector('#product-grid') ||
        doc.querySelector('[id*="ProductGridContainer"]') ||
        doc.querySelector('.collection__results') ||
        doc.querySelector('.collection__main') ||
        doc.querySelector('.product-list') ||
        doc.querySelector('[data-section-type="collection"]')
      );
    }

    function setActiveLink(activeLink) {
      links.forEach(function(link) {
        link.classList.remove('is-active');
      });

      activeLink.classList.add('is-active');
    }

    links.forEach(function(link) {
      link.addEventListener('click', async function(event) {
        event.preventDefault();

        const targetUrl = link.getAttribute('href');
        if (!targetUrl || link.classList.contains('is-active')) return;

        nav.classList.add('is-loading');

        try {
          const response = await fetch(targetUrl, {
            credentials: 'same-origin'
          });

          const html = await response.text();
          const parser = new DOMParser();
          const newDoc = parser.parseFromString(html, 'text/html');

          const currentCollectionArea = findCollectionArea(document);
          const newCollectionArea = findCollectionArea(newDoc);

          if (!currentCollectionArea || !newCollectionArea) {
            window.location.href = targetUrl;
            return;
          }

          currentCollectionArea.innerHTML = newCollectionArea.innerHTML;

          setActiveLink(link);

          window.scrollTo({
            top: nav.getBoundingClientRect().top + window.pageYOffset - 90,
            behavior: 'smooth'
          });

          document.dispatchEvent(new Event('shopify:section:load'));
          document.dispatchEvent(new Event('theme:cart:refresh'));

        } catch (error) {
          console.warn('CURVJEANS AJAX collection nav error:', error);
          window.location.href = targetUrl;
        } finally {
          nav.classList.remove('is-loading');
        }
      });
    });
  });
</script>
